(function(){
'use strict';
var STATE_KEY='welog-pair-sheet-v4';
function readState(){try{return JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}}catch(e){return{}}}
function waitReady(sheet){return Promise.resolve().then(async function(){if(document.fonts){try{await document.fonts.ready}catch(e){}}var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})})}
function hideEditorOverlays(sheet){var list=[].slice.call(sheet.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.st-v2-lock,.st-v2-del,.st-v2-resize,.direct-crop-ui,.guide-line'));var prev=list.map(function(el){return{el:el,visibility:el.style.visibility}});list.forEach(function(x){x.style.visibility='hidden'});return function(){prev.forEach(function(x){x.el.style.visibility=x.visibility})}}
async function saveLive(){var sheet=document.getElementById('sheet'),btn=document.getElementById('printBtn');if(!sheet||!btn||!window.html2canvas)return;var old=btn.textContent,restore=function(){};btn.disabled=true;btn.textContent='저장 중…';try{await waitReady(sheet);restore=hideEditorOverlays(sheet);await new Promise(function(r){requestAnimationFrame(r)});var rect=sheet.getBoundingClientRect(),w=Math.max(sheet.offsetWidth,Math.round(rect.width)),h=Math.max(sheet.offsetHeight,sheet.scrollHeight,Math.round(rect.height));var canvas=await window.html2canvas(sheet,{scale:Math.max(2,window.devicePixelRatio||1),useCORS:true,allowTaint:false,backgroundColor:null,logging:false,imageTimeout:30000,width:w,height:h,scrollX:0,scrollY:0,windowWidth:Math.max(window.innerWidth,w+64),windowHeight:Math.max(window.innerHeight,h+64)});var blob=await new Promise(function(res,rej){canvas.toBlob(function(b){b?res(b):rej(new Error('blob'))},'image/png')});var u=URL.createObjectURL(blob),a=document.createElement('a'),name=((readState().pairName||'WeLog').trim()||'WeLog');a.href=u;a.download=name+'.png';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(u)},1200)}catch(e){console.error('live sheet save failed',e);alert('PNG 저장에 실패했습니다. 다시 시도해 주세요.')}finally{try{restore()}catch(e){}btn.disabled=false;btn.textContent=old}}
function install(){var old=document.getElementById('printBtn');if(!old||old.dataset.liveSaveReady)return;var b=old.cloneNode(true);b.dataset.liveSaveReady='1';old.replaceWith(b);b.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();saveLive()},true)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);else install();setTimeout(install,200);
})();